    private List<Channel>? channels;
    private List<Message>? messages;
    private List<ThreadSummary>? threadSummaries;
    private Channel? activeChannel;
    private int activeChannelId;

    private string newMessageText = "";
    private int? hoveredMessageId;
    private int? emojiPickerMessageId;

    // Pagination
    private const int PageSize = 30;
    private int loadedCount;
    private bool isLoadingMore;
    private bool allMessagesLoaded;

    // Thread state
    private bool threadOpen;
    private Message? threadRootMessage;
    private List<Message>? threadReplies;
    private string threadReplyText = "";

    private ElementReference messageListRef;

    private static readonly string[] commonEmojis = ["👍", "❤️", "😂", "🎉", "😮", "👀"];

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannelAsync(channels[0].Id);
        }
    }

    private async Task SelectChannelAsync(int channelId)
    {
        activeChannelId = channelId;
        activeChannel = channels?.FirstOrDefault(c => c.Id == channelId);
        loadedCount = 0;
        allMessagesLoaded = false;
        messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        loadedCount = messages.Count;
        allMessagesLoaded = messages.Count < PageSize;
        await ChatService.MarkChannelReadAsync(channelId);
        BuildThreadSummaries();
        CloseThread();

        // Refresh channels to update unread counts
        channels = await ChatService.GetChannelsAsync();
    }

    private async Task HandleScrollAsync()
    {
        if (isLoadingMore || allMessagesLoaded) return;

        var scrollTop = await JS.InvokeAsync<double>("eval", "document.querySelector('.message-list')?.scrollTop ?? 1");
        if (scrollTop < 50)
        {
            await LoadOlderMessagesAsync();
        }
    }

    private async Task LoadOlderMessagesAsync()
    {
        if (isLoadingMore || allMessagesLoaded) return;
        isLoadingMore = true;

        var olderMessages = await ChatService.GetMessagesAsync(activeChannelId, loadedCount, PageSize);
        if (olderMessages.Count < PageSize)
        {
            allMessagesLoaded = true;
        }

        if (olderMessages.Count > 0)
        {
            messages = [..olderMessages, ..messages!];
            loadedCount += olderMessages.Count;
            BuildThreadSummaries();
        }

        isLoadingMore = false;
    }

    private async Task SendMessageAsync()
    {
        if (string.IsNullOrWhiteSpace(newMessageText)) return;

        var sent = await ChatService.SendMessageAsync(activeChannelId, newMessageText.Trim(), null);
        messages ??= [];
        messages.Add(sent);
        newMessageText = "";
        await ScrollToBottomAsync();
    }

    private async Task HandleMessageKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await SendMessageAsync();
        }
    }

    private async Task HandleThreadKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await SendThreadReplyAsync();
        }
    }

    private async Task ReactAsync(int messageId, string emoji)
    {
        await ChatService.AddReactionAsync(messageId, emoji);
        emojiPickerMessageId = null;

        // Refresh messages to show updated reactions
        if (messages is not null)
        {
            var refreshed = await ChatService.GetMessagesAsync(activeChannelId, 0, loadedCount);
            messages = refreshed;
        }

        if (threadOpen && threadRootMessage is not null)
        {
            threadReplies = await ChatService.GetThreadAsync(threadRootMessage.Id);
        }
    }

    private void ToggleEmojiPicker(int messageId)
    {
        emojiPickerMessageId = emojiPickerMessageId == messageId ? null : messageId;
    }

    private async Task OpenThreadAsync(int rootMessageId)
    {
        var allMessages = messages?.Concat(threadReplies ?? []);
        threadRootMessage = allMessages?.FirstOrDefault(m => m.Id == rootMessageId);

        if (threadRootMessage is null)
        {
            // Fetch thread to find root
            var threadMessages = await ChatService.GetThreadAsync(rootMessageId);
            threadRootMessage = threadMessages.FirstOrDefault(m => m.Id == rootMessageId);
            threadReplies = threadMessages.Where(m => m.Id != rootMessageId).ToList();
        }
        else
        {
            threadReplies = await ChatService.GetThreadAsync(rootMessageId);
            threadReplies = threadReplies.Where(m => m.Id != rootMessageId).ToList();
        }

        threadReplyText = "";
        threadOpen = true;
    }

    private void CloseThread()
    {
        threadOpen = false;
        threadRootMessage = null;
        threadReplies = null;
        threadReplyText = "";
    }

    private async Task SendThreadReplyAsync()
    {
        if (string.IsNullOrWhiteSpace(threadReplyText) || threadRootMessage is null) return;

        var reply = await ChatService.SendMessageAsync(activeChannelId, threadReplyText.Trim(), threadRootMessage.Id);
        threadReplies ??= [];
        threadReplies.Add(reply);
        threadReplyText = "";
        BuildThreadSummaries();
    }

    private void BuildThreadSummaries()
    {
        if (messages is null) { threadSummaries = null; return; }

        threadSummaries = messages
            .Where(m => m.ReplyToId is not null)
            .GroupBy(m => m.ReplyToId!.Value)
            .Select(g => new ThreadSummary(g.Key, g.Count(), g.Max(m => m.SentAt)))
            .ToList();
    }

    private async Task ScrollToBottomAsync()
    {
        await JS.InvokeVoidAsync("eval",
            "setTimeout(() => { const el = document.querySelector('.message-list'); if(el) el.scrollTop = el.scrollHeight; }, 50)");
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt.ToUniversalTime();
        if (diff.TotalSeconds < 60) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d, yyyy");
    }

    private static string Truncate(string text, int maxLength)
        => text.Length <= maxLength ? text : text[..(maxLength - 1)] + "…";
